from jsonb_to_recordset($json$[{"id":"che-so-113","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dental and laboratory amalgams are solutions in which the solvent is","options":["mercury dissolving a metal","water dissolving sugar","ethanol dissolving iodine","air dissolving water vapour"],"answer_index":0,"explanation":"An amalgam is a metal (or metals) dissolved in mercury.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"types-solubility","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-114","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A sealed soda is opened and then left in the sun. CO2 escapes more freely because","options":["both the pressure drop and the temperature rise lower gas solubility","only the pressure change matters; heat raises gas solubility","heating alone increases the Henry solubility","solids and gases respond identically to pressure"],"answer_index":0,"explanation":"Henry’s law: less partial pressure means less dissolved gas, and warming further decreases gas solubility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"types-solubility","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-115","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mass percent of a dissolved substance is 100 times the ratio of","options":["mass of solute to mass of solution","moles of solute to litres of solution","moles of solute to kilograms of solvent","volume of solute to volume of solvent"],"answer_index":0,"explanation":"w/w % = (mass of solute / mass of solution) × 100.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-116","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mole fraction of component A in a binary mixture equals","options":["$n_A / (n_A + n_B)$","$n_A / n_B$","mass of A / mass of B","$M_A / M_B$"],"answer_index":0,"explanation":"Mole fraction is the mole share of that component among all moles present.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-117","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molarity counts the moles of solute present in","options":["one litre of solution","one kilogram of solvent","one litre of pure solvent","one kilogram of solution"],"answer_index":0,"explanation":"M = moles of solute / volume of solution in litres.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-118","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molality places in the denominator the","options":["volume of solution in litres","mass of solvent in kilograms","mass of the whole solution in grams","volume of the solute"],"answer_index":1,"explanation":"m = moles of solute / kilograms of solvent, so it is independent of solution volume.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-119","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Parts per million by mass is defined as","options":["$10^6$ times (mass of solute / mass of solution)","$10^3$ times (mass of solute / mass of solution)","100 times (moles of solute / litres)","moles of solute per kilogram of solvent"],"answer_index":0,"explanation":"ppm (w/w) = $10^6 \\times w_{\\mathrm{solute}} / w_{\\mathrm{solution}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-120","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Among the usual concentration units, the one that does not shift when the solution is warmed is","options":["molarity","normality","molality","formality based on volume"],"answer_index":2,"explanation":"Molality uses solvent mass, which does not expand with temperature; molarity uses volume.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-121","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Adding the mole fractions of every component of a solution yields","options":["zero","exactly one","one hundred","the molarity"],"answer_index":1,"explanation":"Mole fractions are fractions of a whole, so $\\sum x_i = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-122","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Volume percent is the concentration unit most often quoted for","options":["solid metal alloys","liquid–liquid mixtures","gas occluded in a metal","ionic unit cells"],"answer_index":1,"explanation":"v/v % is convenient when both solute and solvent are liquids.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-123","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 1.0 molal aqueous preparation contains 1.0 mol of solute dissolved in","options":["1.0 L of solution","1.0 kg of water","1.0 kg of solution","1.0 L of water"],"answer_index":1,"explanation":"Molality is moles per kilogram of solvent, not per litre of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-124","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mass/volume percent is 100 times the ratio of","options":["mass of solute to volume of solution","volume of solute to mass of solvent","moles of solute to kilograms of solvent","mass of solvent to mass of solute"],"answer_index":0,"explanation":"w/v % = (mass of solute / volume of solution) × 100, with consistent units.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
